import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"天风姤","description":"周易折中 - 天风姤","frontmatter":{"title":"天风姤","description":"周易折中 - 天风姤"},"headers":[],"relativePath":"zh/classics/zhezhong/050.md","filePath":"zh/classics/zhezhong/050.md"}'),h={name:"zh/classics/zhezhong/050.md"};function n(d,a,p,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="天风姤" tabindex="-1">天风姤 <a class="header-anchor" href="#天风姤" aria-label="Permalink to “天风姤”">​</a></h1><h3 id="《程传》" tabindex="-1">《程传》 <a class="header-anchor" href="#《程传》" aria-label="Permalink to “《程传》”">​</a></h3><p>〈姤序卦〉：“夬，决也。决必冇遇，故受之以姤。姤，遇也。决判也，物之决判则有遇合，本合则何遇？姤所以次夬也。为卦干上巽下，以二体言之，风行天下，天之下者万物也，风之行无不经触，乃遇之象，又一阴始生于下，阴与阳遇也，故为姤。”</p><p>姤：女壮，勿用取女</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>姤，遇也。决尽则为纯干，四月之卦。至姤然后一阴可见，而为五月之卦。以其本非所望，而卒然值之，如不期而遇者，故为遇。遇已非正，又一阴而遇五阳，则女德不贞而壮之甚也。取以自配，必害乎阳，故其象占如此。</p><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>一阴始生，自是而长，渐以盛大，是女之将长壮也。阴长则阳消，女壮则男弱，故戒勿用取如是之女。取女者，欲其柔和顺从以成家道，姤乃方进之阴，渐壮而敌阳者，是以不可取也。女渐壮则失男女之正，家道败矣。姤虽一阴甚微，然有渐壮之道，所以戒也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>孔氏颖达曰 ：姤，遇也。此卦一柔而遇五刚，故名为姤。施之于人，则是一女而遇五男，为壮至甚。故戒之曰：“此女壮甚，勿用取此女也。”</li></ul><p>孔氏颖达曰 ：姤，遇也。此卦一柔而遇五刚，故名为姤。施之于人，则是一女而遇五男，为壮至甚。故戒之曰：“此女壮甚，勿用取此女也。”</p><ul><li>郭氏雍曰 ：阳至四五而后言壮，姤一阴方长即为壮者，亦见君子小人之情不同也。</li></ul><p>郭氏雍曰 ：阳至四五而后言壮，姤一阴方长即为壮者，亦见君子小人之情不同也。</p><ul><li>冯氏椅曰 ：古文“姤”作“遘”，遇也，亦婚媾也。以女遇男为象。王洙《易》改为今文为“姤”，杂卦犹是古文，郑本同。</li></ul><p>冯氏椅曰 ：古文“姤”作“遘”，遇也，亦婚媾也。以女遇男为象。王洙《易》改为今文为“姤”，杂卦犹是古文，郑本同。</p><ul><li>胡氏炳文曰 ：女壮，诸家皆以为一阴有将盛之渐，本义以为一阴当五阳已有女壮之象。</li></ul><p>胡氏炳文曰 ：女壮，诸家皆以为一阴有将盛之渐，本义以为一阴当五阳已有女壮之象。</p><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>女壮之义，非以一阴始生于下为壮，亦非以一阴独当五阳为壮。盖卦以阴为主，阴而为主，即是壮也。</p><p>此处AI有独到的见解：姤卦一阴初生，虽未盛大，但已显现其为主之势，故曰女壮。此时若取其女，则必害乎阳，因此戒之曰“勿用取女”。这一解释强调了阴为主即为壮的观点，与传统解释有所不同，但亦有其独特的见解和逻辑。</p><p>象曰：天下有风姤，后以施命诰四方</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>风行天下，无所不周，为君后者观其周遍之象，以施其命令，周诰四方也。风行地上与天下有风，皆为周遍庶物之象。而行于地上，遍触万物，则为观，经历观省之象也；行于天下，周遍四方，则为姤，施发命令之象也。诸象或称先王，或称后，或称君子大人。称先王者，先王所以立法制、建国作乐、省方敕法、闭关育物、享帝皆是也。称后者，后王之所为也，财成天地之道，施命诰四方是也。君子则上下之通称，大人者王公之通称。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li>龚氏焕曰：天下有风姤与风行地上观相似，故在姤则曰施命诰四方，在观则曰省方观民设教。曰施、曰诰，自上而下，天下有风之象也；曰省、曰观，周历遍览，风行地上之象也。案巽之申命因有积弊而振饬之也，姤之施命与巽正同，盖在三画之卦为巽者，在六画之卦即为姤也。施命、申命，所以消隠慝、除积弊，法风之吹散伏阴也。</li></ul><p>彖曰：姤，遇也，柔遇刚也</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>释卦名。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>姤之义遇也。卦之为姤，以柔遇刚也。一阴方生，始与阳相遇也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>赵氏汝梅曰 ：柔遇刚者，明非刚遇柔也。</p></li><li><p>林氏希元曰 ：依本义是阳遇阴，依彖传是阴遇阳。彖传乃本义以一阴而遇五阳，意盖彖传是为下文“勿用取女，不可与长”而设也。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>柔遇刚者，以柔为主也。如臣之专制，如牝之司晨，得不谓壮乎？故不复释“女壮”，而直释“勿用取女”之义。</p><p>勿用取女，不可与长也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>释卦辞。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>一阴既生，渐长而盛。阴盛则阳衰矣。取女者欲长久而成家也，此渐盛之阴将消胜于阳，不可与之长久也。凡女子、小人、夷狄，势苟渐盛，何可与久也？故戒勿用取如是之女。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郑氏康成曰 ：一阴承五阳，苟相遇耳，非礼之正。女壮如是，故不可娶。</p></li><li><p>王氏肃曰 ：女不可娶，以其不正，不可与长久也。</p></li><li><p>苏氏轼曰 ：姤者，所遇而合无适应之谓也。故其女不可与长。</p></li><li><p>李氏舜臣曰 ：以一阴遇五阳，女下于男，有女不正之象，故曰“勿用取女”。咸所以取女吉者，以男下女，得婚姻正礼故也。若蒙之六三以阴而先求阳，其行不顺，故亦曰“勿用取女”。</p></li></ul><p>天地相遇，品物咸章也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦体言。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>阴始生于下与阳相遇，天地相遇也。阴阳不相交遇则万物不生，天地相遇则化育庶类，品物咸章，万物章明也。</p><p>刚遇中正，天下大行也</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>指九五。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>以卦才言也。五与二皆以阳刚居中与正以中正相遇也。君得刚中之臣，臣遇中正之君，君臣以刚阳遇中正，其道可以大行于天下矣。</p><p>姤之时义大矣哉</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>几㣲之际，圣人所谨。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>赞姤之时与姤之义至大也。天地不相遇则万物不生，君臣不相遇则政治不兴，圣贤不相遇则道德不亨，事物不相遇则功用不成。姤之时与义皆甚大也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类 ：问“姤之时义大矣哉”，本义云“几㣲之际，圣人所谨”，与伊川之说不同何也？曰上面说“天地相遇”至“天下大行也”，而不好之渐已生于微矣，故当谨于此。</p></li><li><p>吴氏曰慎曰 ：姤为阴遇阳之卦，阴阳有当遇者，如天地相遇及君臣夫妇之类，是不能相无者；有遇而当制者，如“勿用取女”及小人妄念之类，是不容并立者。时义大矣哉，程传重“遇”字，专以遇之善者言；本义重“制”字，专以遇之不善者言。窃意此语总承上文两端而言可也。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>必如天地之相遇而后品物咸章也，必如此卦以群刚遇中正之君，然后天下大行也。苟天地之相遇而有阴邪干于其间，君臣之相遇而有宵类介乎其侧，则在天地为伏阴，在国家为隠慝，而有女壮之象矣。</p><p>/books/106/44/1.html</p><p>初六 系于金柅，贞吉；有攸往，见凶。羸豕孚蹢躅</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>柅，所以止车，以金为之，其刚可知。一阴始生，静正则吉，往进则凶。故以二义戒小人，使不害于君子，则有吉而无凶。然其势不可止也，故以“羸豕孚蹢躅”晓君子，使深为之备云。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>姤，阴始生而将长之卦。一阴生则长而渐盛，阴长则阳消，小人道长也。制之当于其微而未盛之时。柅，止车之物，金为之，坚强之至也。止之以金柅而又系之，止之固也。固止使不得进，则阳刚贞正之道吉也。使之进往，则渐盛而害于阳，是见凶也。“羸豕孚蹢躅”，圣人重为之戒，言阴虽甚微，不可忽也。豕，阴躁之物，故以为况。羸弱之豕虽未能强猛，然其中心在乎蹢躅（跳踯）。阴微而在下，可谓羸矣，然其中心常在乎消阳也。君子小人异道，小人虽微弱之时，未尝无害君子之心。防于微，则无能为矣。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>丘氏富国曰 ：姤之所以为姤者，在此一爻。一阴始生，非以金柅系之，则柔道何所牵制而不敢进？系之所以防之也。</li></ul><p>丘氏富国曰 ：姤之所以为姤者，在此一爻。一阴始生，非以金柅系之，则柔道何所牵制而不敢进？系之所以防之也。</p><ul><li>胡氏炳文曰 ：彖总一卦而言，则以一阴而当五阳，故于女为壮。爻指一画而言，五阳之下一阴甚微，故于豕为羸。壮可畏也，羸不可忽也。</li></ul><p>胡氏炳文曰 ：彖总一卦而言，则以一阴而当五阳，故于女为壮。爻指一画而言，五阳之下一阴甚微，故于豕为羸。壮可畏也，羸不可忽也。</p><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>一阴穷于上，众以为无凶矣，而曰“终有凶”，防其后之辞也。一阴伏于下，众未觉其凶矣，而曰“有攸往，见凶”，察于先之辞也。阴阳消息，循环无端，能察于先即所以防其后，能防其后即所以察于先也。</p><p>象曰：系于金柅，柔道牵也</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>牵，进也。以其进，故止之。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>牵者，引而进也。阴始生而渐进，柔道方牵也。击之于金柅，所以止其进也。不使进，则不能消正道，乃贞吉也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：柔道牵者，阴柔之道必须有所牵系也。</p></li><li><p>郑氏汝谐曰：此羸豕也，力虽微而其志则蹢躅，惟信其蹢躅，则不可不有所牵制，故曰柔道牵也。</p></li><li><p>赵氏汝梅曰：姤之初言系、言牵，恶阴之长而止之也。</p></li></ul><p>九二：包有鱼，无咎，不利宾</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>鱼，阴物。二与初遇，为“包有鱼”之象。然制之在已，故犹可以无咎。若不制而使遇于众，则其为害广矣。故其象占如此。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>姤，遇也。二与初密比相遇者也。在他卦则初正应于四，在姤则以遇为重。相遇之道，主于专一。二之刚中遇初，固以诚然。初之阴柔，群阳在上而又有所应者，其志所求也。阴柔之质，鲜克贞固。二之于初，难得其诚心矣。所遇不得其诚心，遇道之乖也。包者，苴裹也。鱼，阴物之美者。阳之于阴，其所悦美，故取鱼象。二于初，若能固畜之如包苴之有鱼，则于遇为无咎矣。宾，外来者也。不利宾，包苴之鱼岂能及宾？谓不可更及外人也。遇道当专一，二则杂矣。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>陆氏希声曰 ：不正之阴与刚中之二相比，能包而有之，使其邪不及于外。</li></ul><p>陆氏希声曰 ：不正之阴与刚中之二相比，能包而有之，使其邪不及于外。</p><ul><li>李氏开曰 ：剥之贯鱼，姤之包有鱼，皆能制阴者也。</li></ul><p>李氏开曰 ：剥之贯鱼，姤之包有鱼，皆能制阴者也。</p><ul><li>胡氏炳文曰 ：包如包苴之包，容之于内而制之，使不得逸于外也。</li></ul><p>胡氏炳文曰 ：包如包苴之包，容之于内而制之，使不得逸于外也。</p><ul><li>何氏楷曰 ：“包”字与“系豕”、“包瓜”同意。古之小人所以乱天下者，往往君子激之也。二曰“包有鱼”，则不视小人为异类而直以兼容之量包之。既下迩之使近，亦不激之使无所容，其何咎焉。</li></ul><p>何氏楷曰 ：“包”字与“系豕”、“包瓜”同意。古之小人所以乱天下者，往往君子激之也。二曰“包有鱼”，则不视小人为异类而直以兼容之量包之。既下迩之使近，亦不激之使无所容，其何咎焉。</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>制阴之义，不取诸九四之相应而取诸九二之相比者，阴阳主卦皆以近比者为亲切而处之，又有中有不中焉。故复六四之独复，亦不如六二休复之为美也。夬五近上，则有苋陆之嫌；姤二比初，独不以阴邪为累乎？曰：夬之阴，其势极矣，如病之既剧，如乱之已成，非有以除去之不可。姤则阴始生也，如病将发，如乱初萌，豫防而早冶之，则不至于盛长矣。观乎“不利宾”之戒，未尝不以阴邪之渐驯为谆谆也。《诗》云：“敝笱在梁，其鱼鲂鳏。齐子归止，其从如云。”是不能制之而使及宾之验矣。</p><p>象曰：包有鱼，义不及宾也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>二之遇初，不可使有二于外，当如包苴之有鱼，包苴之鱼，义不及于宾客也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>吴氏曰愼曰：九二既包有鱼，则当尽其防制之责，以义言之，不可使遇于宾也。若不制而使遇于宾，则失其义矣。</li></ul><p>九三：臀无肤，其行次且，厉无大咎</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>九三过刚不中，下不遇于初，上无应于上，居则不安，行则不进。故其象占如此。然既无所遇，则无阴邪之伤，故虽危厉而无大咎也。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>二与初既相遇，三说初而密比于二，非所安也，又为二所忌恶。其居不安，若臀之无肤也。处既不安，则当去之。而居姤之时，志求乎遇，一阴在下是所欲也。故处虽不安，而其行则又次且也（次且，进难之状，谓不能遽舍也）。然三刚正而处巽，有不终迷之义。若知其不正而怀危惧，不敢妄动，则可以无大咎也。非义求遇，固已有咎矣，知危而止，则不至于大也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>李氏简曰 ：居则臀在下，故《困》初六言臀；行则臀在中，故《夬》《姤》三四言臀。</li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>臀无肤之义与夬四同。其行次且，志欲制阴也。非其位任而欲制之，有危道焉。然于义则无咎。</p><p>象曰：其行次且，行未牵也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>其始志在求遇于初，故其行迟迟，未牵不促其行也。既知危而改之，故未至于大咎也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>郭氏雍曰：无肤次且之厉，盖未尝牵勉而妄行焉，是以至此。</li></ul><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>易中言“牵”者，自小畜至此，皆当为牵制之义。</p><p>九四：包无鱼，起凶</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>初六正应已遇于二而不及于己，故其象占如此。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>包者，所裹畜也；鱼，所美也。四与初为正应，当相遇者也。而初已遇于二矣，失其所遇，犹包之无鱼，亡其所有也。四当姤遇之时，居上位而失其下，下之离由已之失徳也。四之失者，不中正也。以不中正而失其民，所以凶也。曰：“初之从二以比近也，岂四之罪乎？”曰：“在四而言，义当有咎。不能保其下，由失道也。岂有上不失道而下离者乎？”遇之道，君臣、民主、夫妇、朋友皆在焉。四以下睽，故主民而言。为上而下离，必有凶变起者，将生之谓。民心既离，难将作矣。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>吴氏曰 、 愼曰 ：九三以不遇阴而无大咎，上九以不遇阴而无咎，四则包无鱼起凶，何也？盖初六本其正应，当遇而不遇故也。</li></ul><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>四与初正应，当制阴之任者也。然不能制之，而为“包无鱼”之象。何也？曰：此与夬之九三同，当决阴制阴之任，而德非中正。故一则刚壮而怀愠怒，一则疾恶而胥绝远，无包容之量，无制服之方。故以是爻德而适犯卦义，“取女”之戒，则其起凶宜矣。《书》曰：“寛而有制，有容德乃大。”又曰：“尔无忿疾于顽。”是“包有鱼”、“无鱼”之所由分也。</p><p>象曰：无鱼之凶，远民也</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>民之去已，犹已远之。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>下之离，由已致之。远民者，已远之也。为上者有以使之离也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>余氏本曰：言其使民失道，无以结民之心，致民之去，由已之远乎民也。</li></ul><h3 id="案-8" tabindex="-1">案 <a class="header-anchor" href="#案-8" aria-label="Permalink to “案”">​</a></h3><p>九四因与阴相应，故恶而欲远之，正如夬三“壮于頄”之意。徒欲远之而不能容之制之，此所以“包无鱼”也。君子之于小人也，惟其能容之，是以能制之。不能容之，则彼自绝矣。欲以力制，不亦难乎？书曰“民可近不可下”，此之谓也。</p><p>九五：以杞包瓜，含章有陨自天</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>瓜，阴物之在下者，甘美而善溃。杞，高大坚实之木也。五以阳刚中正主卦于上，而下防始生必溃之阴，其象如此。然阴阳迭胜，时运之常。若能含晦章美，静以制之，则可以回造化矣。有陨自天，本无而倏有之象也。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>九五下亦无应，非有遇也。然得遇之道，故终必有遇。夫上下之遇，由相求也。杞，高木而叶大，处高体大而可以包物者。杞也，美实之在下者瓜也，美而居下者侧微之贤之象也。九五尊居君位，而下求贤才，以至高而求至下，犹以杞叶而包瓜，能自降屈如此。又其内蕴中正之德，充实章美。人君如是，则无有不遇所求者也。虽屈己求贤，若其德不正，贤者不屑也。故必含蓄章美，内积至诚，则有陨自天矣。犹云自天而降，言必得之也。自古人君至诚降屈，以中正之道求天下之贤，未有不遇者也。高宗感于梦寐，文王遇于渔钓，皆由是道也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰 ：鱼与瓜皆阴物。二与初遇，故“包有鱼”。五与初无相遇之道，犹以高大之杞而包在地之瓜也。然瓜虽始生而必溃，九五阳刚中正，能含晦章美，静以待之。是虽阴阳消长，时运之常，而造化未有不可回者。姤其将可转而为复乎？</li></ul><p>胡氏炳文曰 ：鱼与瓜皆阴物。二与初遇，故“包有鱼”。五与初无相遇之道，犹以高大之杞而包在地之瓜也。然瓜虽始生而必溃，九五阳刚中正，能含晦章美，静以待之。是虽阴阳消长，时运之常，而造化未有不可回者。姤其将可转而为复乎？</p><ul><li>俞氏琰曰 ：含即包之谓，其初含蓄不露。一旦瓜熟蒂脱，自杞坠地，故曰“含章有陨自天”。</li></ul><p>俞氏琰曰 ：含即包之谓，其初含蓄不露。一旦瓜熟蒂脱，自杞坠地，故曰“含章有陨自天”。</p><ul><li>林氏希元曰 ：含章不是全无所事，是用意周密，不动声色而自有以消患于方萌也。</li></ul><p>林氏希元曰 ：含章不是全无所事，是用意周密，不动声色而自有以消患于方萌也。</p><h3 id="案-9" tabindex="-1">案 <a class="header-anchor" href="#案-9" aria-label="Permalink to “案”">​</a></h3><p>五为卦主，而与阴无比应，得卦“勿用取女”之义也。夫与阴虽无比应，而为卦主，则有制阴之任焉。故极言脩徳回天之道。</p><p>象曰：九五含章中正也，有陨自天，志不舍命也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>所谓含章，谓其含蕴中正之德也。德充实则成章而有辉光。命，天理也；舍，违也。至诚中正，屈已求贤，存志合于天理，所以有陨自天，必得之矣。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰：阴长而消阳，天之命也，有以胜之；人之志也，君子不以命废志。故九五之志坚，则必有自天而陨者。言人之至者，天不能胜也。</p></li><li><p>杨氏启新曰：阴阳迭胜，天运自然。而心心念念不舍天命，以静制之，此所以挽回造化也。</p></li></ul><h3 id="案-10" tabindex="-1">案 <a class="header-anchor" href="#案-10" aria-label="Permalink to “案”">​</a></h3><p>诗云“桑之落矣，其黄而陨”，故有陨自天，谓天时既至而瓜陨也。虽天命之必然，亦由君子积诚脩德与之符会。故曰“志不舍命”。</p><p>上九：姤其角，吝无咎</p><h3 id="本义-13" tabindex="-1">本义 <a class="header-anchor" href="#本义-13" aria-label="Permalink to “本义”">​</a></h3><p>角，刚乎上者也。上九以刚居上而无位，不得其遇，故其象占与九三类。</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>至刚而在最上者，角也。九以刚居上，故以角为象。人之相遇，由降屈以相从，和顺以相接，故能合也。上九高亢而刚极，人谁与之？以此求遇，固可吝也已。则如是，人之远之，非他人之罪也，由己致之，故无所归咎。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li>徐氏几曰 ：上九处姤之穷，与初无遇，虽吝，然亦无咎。阴不必遇也。</li></ul><p>徐氏几曰 ：上九处姤之穷，与初无遇，虽吝，然亦无咎。阴不必遇也。</p><ul><li>胡氏炳文曰 ：九三以刚居下卦之上，于初阴无所遇，故虽厉而无大咎。上九以刚居上卦之上，于初阴亦不得其遇，故虽吝而亦无咎。遇本非正，不遇不足为咎也。</li></ul><p>胡氏炳文曰 ：九三以刚居下卦之上，于初阴无所遇，故虽厉而无大咎。上九以刚居上卦之上，于初阴亦不得其遇，故虽吝而亦无咎。遇本非正，不遇不足为咎也。</p><h3 id="案-11" tabindex="-1">案 <a class="header-anchor" href="#案-11" aria-label="Permalink to “案”">​</a></h3><p>此爻亦与夬初反对，皆与阴绝远者也。不与阴遇，不能制阴，故可吝。然非其事任也，故无咎。此如避世之士，不能救时，而亦身不与乱者也。</p><p>象曰：姤其角，上穷吝也</p><h3 id="程传-18" tabindex="-1">程传 <a class="header-anchor" href="#程传-18" aria-label="Permalink to “程传”">​</a></h3><p>既处穷上，刚亦极矣，是上穷而致吝也。以刚极居高而求遇，不亦难乎？</p><h3 id="案-12" tabindex="-1">案 <a class="header-anchor" href="#案-12" aria-label="Permalink to “案”">​</a></h3><p>不与阴遇，虽无咎，然君子终以不能济时为可羞。为其身在事外，所处之穷故尔。</p>',173)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
